#!/usr/bin/env node
/**
 * SyncOut patch v6.5 — run from the repo root after v6.4:   node syncout-patch-v6.5.js
 *
 * Fix: "Booking requested" froze — it now always moves on, with real buttons:
 *      "Send on WhatsApp" (booking details pre-filled) and "View my ticket".
 * Admin alerts: live pop-ups with a chime for every booking, payment and guestlist
 *      request; "N new since you last checked"; push notifications on the admin's
 *      phone; an installable "SyncOut Admin" app that opens on the dashboard.
 * Accounts at checkout: a new email gets an account and is logged in right away;
 *      an existing email gets the booking attached (no auto-login). Set a password later.
 * Entry cards: printable QR + barcode + every detail for each booking; the door shows
 *      full details; scanner guns work at /door; guests' tickets carry a barcode too.
 */
"use strict";

const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { execSync } = require("child_process");

const DRY = process.argv.includes("--dry");
const NO_INSTALL = process.argv.includes("--no-install");
const BACKUP = path.join(".patch-backups", "v6.5");

if (!fs.existsSync("src/lib/promos.ts")) {
  console.error("\n  This repo doesn't have v6.4 yet — apply syncout-patch-v6.4.js first, then this one.\n");
  process.exit(1);
}

if (!fs.existsSync("package.json")) {
  console.error("\n  Run this from the repo root (no package.json here).\n");
  process.exit(1);
}
try {
  const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
  if (pkg.name !== "syncout") {
    console.error("\n  This is the '" + pkg.name + "' repo, not syncout.\n");
    process.exit(1);
  }
} catch {
  console.error("\n  package.json could not be read.\n");
  process.exit(1);
}

